function App() {
  const lang = useLang()
  const T = lang === 'it' ? itTranslations : null
  const routerLocation = useLocation()
  const navigate = useNavigate()
  const [isPortalAuthenticated, setIsPortalAuthenticated] = useState(() => localStorage.getItem('portalAuth') === 'true')
  // IMPORTANT: never bootstrap isAdminSession from localStorage.
  // Always verify against the DB before routing. Defaulting to false means a legitimate
  // admin sees a brief loading screen, which is far better than a B2B client seeing admin panel.
  const [isAdminSession, setIsAdminSession] = useState(false)
  const [authReady, setAuthReady] = useState(!hasSupabaseConfig)
  const [pendingRecoverySession, setPendingRecoverySession] = useState(false)
  const [hasAcceptedCookies, setHasAcceptedCookies] = useState(() => localStorage.getItem(COOKIE_CONSENT_STORAGE_KEY) === 'accepted')
  const [isContactModalOpen, setIsContactModalOpen] = useState(false)
  const [contactRequestForm, setContactRequestForm] = useState({ name: '', email: '', phone: '' })
  const [isSubmittingContactRequest, setIsSubmittingContactRequest] = useState(false)
  const [contactRequestMessage, setContactRequestMessage] = useState('')
  const [contactRequestError, setContactRequestError] = useState('')
  const registrationsTable = import.meta.env.VITE_B2B_REGISTRATIONS_TABLE || DEFAULT_REGISTRATIONS_TABLE
  const adminsTable = import.meta.env.VITE_B2B_ADMINS_TABLE || 'b2b_admins'
  const requireApproval = import.meta.env.VITE_REQUIRE_B2B_APPROVAL !== 'false'
  const [showBackToTop, setShowBackToTop] = useState(false)
  const [showChatPanel, setShowChatPanel] = useState(false)
  const [showExitIntent, setShowExitIntent] = useState(false)
  const exitIntentShownRef = useRef(false)

  const handleAcceptCookies = useCallback(() => {
    localStorage.setItem(COOKIE_CONSENT_STORAGE_KEY, 'accepted')
    setHasAcceptedCookies(true)
  }, [])

  useEffect(() => {
    const onWindowScroll = () => setShowBackToTop(window.scrollY > 400)
    window.addEventListener('scroll', onWindowScroll, { passive: true })
    return () => window.removeEventListener('scroll', onWindowScroll)
  }, [])

  // Exit-intent detection — show popup when cursor leaves viewport (desktop)
  // or after 60s idle + visible tab switch (mobile)
  useEffect(() => {
    const EXIT_INTENT_STORAGE_KEY = 'gelitup.exit_intent_shown'
    const alreadyDismissed = sessionStorage.getItem(EXIT_INTENT_STORAGE_KEY)
    if (alreadyDismissed) return

    const hasCartItems = () => {
      try {
        const quick = JSON.parse(localStorage.getItem(QUICK_CART_STORAGE_KEY) || '{}')
        return Object.keys(quick).length > 0
      } catch { return false }
    }

    const trigger = () => {
      if (exitIntentShownRef.current) return
      if (localStorage.getItem('portalAuth') === 'true') return // logged-in users get email instead
      if (!hasCartItems()) return
      exitIntentShownRef.current = true
      sessionStorage.setItem(EXIT_INTENT_STORAGE_KEY, '1')
      setShowExitIntent(true)
    }

    // Desktop: mouse leaves viewport top
    const onMouseLeave = (e) => { if (e.clientY <= 0) trigger() }
    document.addEventListener('mouseout', onMouseLeave)

    // Mobile: detect visibility change (switching tabs/apps) after 30s on page
    let mobileTimer = null
    const onVisibilityChange = () => {
      if (document.visibilityState === 'hidden') trigger()
    }
    mobileTimer = setTimeout(() => {
      document.addEventListener('visibilitychange', onVisibilityChange)
    }, 30_000)

    return () => {
      document.removeEventListener('mouseout', onMouseLeave)
      document.removeEventListener('visibilitychange', onVisibilityChange)
      if (mobileTimer) clearTimeout(mobileTimer)
    }
  }, [])

  const openContactModal = useCallback(() => {
    setContactRequestError('')
    setContactRequestMessage('')
    setIsContactModalOpen(true)
  }, [])

  const closeContactModal = useCallback(() => {
    if (isSubmittingContactRequest) return
    setIsContactModalOpen(false)
  }, [isSubmittingContactRequest])

  const setContactField = useCallback((key, value) => {
    setContactRequestForm((current) => ({ ...current, [key]: value }))
  }, [])

  useEffect(() => {
    if (hasSupabaseConfig) {
      return undefined
    }

    localStorage.setItem('portalAuth', String(isPortalAuthenticated))
  }, [isPortalAuthenticated])

  useEffect(() => {
    if (!hasSupabaseConfig || !supabase) {
      return undefined
    }

    let mounted = true

    supabase.auth.getSession().then(async ({ data }) => {
      if (!mounted) return
      if (data.session) {
        // Mark this tab as having an active authenticated session
        sessionStorage.setItem('portalTabActive', 'true')
        // Re-verify admin status on session restore (handles new devices / cleared localStorage)
        try {
          const userEmail = data.session.user?.email
          if (userEmail) {
            const { data: adminRows } = await supabase
              .from(adminsTable)
              .select('email')
              .ilike('email', userEmail)
              .limit(1)
            const isAdmin = Boolean(adminRows?.length)
            if (mounted) {
              setIsAdminSession(isAdmin)
              if (isAdmin) {
                localStorage.setItem('gelitup.admin.session', 'true')
              } else {
                localStorage.removeItem('gelitup.admin.session')
              }
            }
          }
        } catch { /* non-fatal — fall back to localStorage value */ }
      }
      setIsPortalAuthenticated(Boolean(data.session))
      setAuthReady(true)
    })

    const { data: listener } = supabase.auth.onAuthStateChange((event, session) => {
      if (event === 'PASSWORD_RECOVERY') {
        // User arrived via a password-reset email link — flag recovery mode and send to
        // the create-password form.  The ?code= is already consumed by the SDK so we
        // cannot rely on URL params; this event is the only reliable signal.
        setPendingRecoverySession(true)
        navigate('/portal/login?mode=create-password')
        setAuthReady(true)
        return
      }
      if (event === 'SIGNED_IN' && session) {
        // Block authReady until the admin DB check resolves — this eliminates the race
        // condition where ProtectedPortal renders with stale isAdminSession=true before
        // the async check can correct it, routing B2B clients to the admin panel.
        const userEmail = session.user?.email
        setIsPortalAuthenticated(true)
        if (userEmail && supabase) {
          supabase
            .from(adminsTable)
            .select('email')
            .ilike('email', userEmail)
            .limit(1)
            .then(({ data: adminRows }) => {
              const isAdmin = Boolean(adminRows?.length)
              setIsAdminSession(isAdmin)
              if (isAdmin) {
                localStorage.setItem('gelitup.admin.session', 'true')
              } else {
                localStorage.removeItem('gelitup.admin.session')
              }
            })
            .catch(() => {
              setIsAdminSession(false)
              localStorage.removeItem('gelitup.admin.session')
            })
            .finally(() => { setAuthReady(true) })
        } else {
          setIsAdminSession(false)
          localStorage.removeItem('gelitup.admin.session')
          setAuthReady(true)
        }
        return
      }
      if (event === 'SIGNED_OUT') {
        setIsAdminSession(false)
        localStorage.removeItem('gelitup.admin.session')
        setIsPortalAuthenticated(false)
        setAuthReady(true)
        return
      }
      if (session) {
        // Mark this tab active so future TOKEN_REFRESHED / INITIAL_SESSION events pass
        sessionStorage.setItem('portalTabActive', 'true')
      }
      setIsPortalAuthenticated(Boolean(session))
      setAuthReady(true)
    })

    return () => {
      mounted = false
      listener.subscription.unsubscribe()
    }
  }, [])

  useEffect(() => {
    const isHomeRoute = routerLocation.pathname === '/' || routerLocation.pathname === '/home'
    if (!isHomeRoute) {
      return
    }

    const params = new URLSearchParams(routerLocation.search)
    const portalTarget = String(params.get('portal') || '').trim().toLowerCase()

    if (!portalTarget) {
      return
    }

    if (portalTarget === 'login') {
      navigate('/portal/login', { replace: true })
      return
    }

    if (portalTarget === 'admin') {
      navigate('/portal/admin-login', { replace: true })
    }
  }, [navigate, routerLocation.pathname, routerLocation.search])

  const fetchLatestRegistrationByEmail = async (normalizedEmail, selectColumns = '*') => {
    if (!normalizedEmail || !hasSupabaseConfig || !supabase) {
      return { data: null, error: null }
    }

    const queryLatest = async (column) => {
      const { data, error } = await supabase
        .from(registrationsTable)
        .select(selectColumns)
        .ilike(column, normalizedEmail)
        .order('created_at', { ascending: false })
        .limit(1)

      if (error) {
        const missingColumn = /column .* does not exist/i.test(String(error.message || ''))
        if (missingColumn) return { data: null, error: null }
        return { data: null, error }
      }

      return { data: data?.[0] || null, error: null }
    }

    const primaryResult = await queryLatest('contact_email')
    if (primaryResult.error || primaryResult.data) {
      return primaryResult
    }

    return queryLatest('email')
  }

  const handlePortalLogin = async (email, password) => {
    if (hasSupabaseConfig && supabase) {
      const normalizedEmail = String(email || '').trim().toLowerCase()
      const isInternalBypassEmail = PORTAL_INTERNAL_BYPASS_EMAILS.has(normalizedEmail)
      const { error } = await supabase.auth.signInWithPassword({ email: normalizedEmail, password })

      if (error) {
        const authErrorMessage = String(error.message || '').trim()
        const isInvalidCredentials = /invalid login credentials/i.test(authErrorMessage)

        if (!isInvalidCredentials) {
          return {
            ok: false,
            message: authErrorMessage || 'Unable to sign in.',
            applicationStatus: '',
            debugTrace: `login-error:${authErrorMessage || 'unknown'} bypass=${isInternalBypassEmail ? 'yes' : 'no'}`,
          }
        }

        const registrationResult = await fetchLatestRegistrationByEmail(normalizedEmail, 'status, notes')
        const latestRegistration = registrationResult.data || null

        const status = String(latestRegistration?.status || '').trim().toLowerCase()
        const applicationType = latestRegistration ? getApplicationTypeFromRecord(latestRegistration) : 'b2b_order'
        const isDistributorRegistration = applicationType === 'distributor'

        if (isDistributorRegistration && requireApproval && status !== 'approved') {
          if (status === 'rejected') {
            return {
              ok: false,
              message: 'Your B2B application was rejected. Contact distribution support for next steps.',
              applicationStatus: 'rejected',
              debugTrace: 'login-invalid-credentials -> distributor-rejected',
            }
          }

          if (status === 'submitted') {
            return {
              ok: false,
              message: 'Your order request is stored and under processing. Portal sign-in requires an approved distributor application.',
              applicationStatus: 'submitted',
              debugTrace: 'login-invalid-credentials -> distributor-submitted',
            }
          }

          return {
            ok: false,
            message: 'Your B2B application is pending approval. Access is enabled after manual review.',
            applicationStatus: 'pending',
            debugTrace: 'login-invalid-credentials -> distributor-pending',
          }
        }

        const signUpResult = await supabase.auth.signUp({
          email: normalizedEmail,
          password,
          options: {
            emailRedirectTo: `${window.location.origin}/portal/login`,
          },
        })

        const signUpMessage = signUpResult?.error?.message || ''
        const isAlreadyRegistered = /already registered|already been registered/i.test(signUpMessage)
        const isExistingAccount = isExistingUserSignUpResult(signUpResult)
        let canSignInNow = hasActiveSignUpSession(signUpResult)

        if (signUpResult.error && !isAlreadyRegistered) {
          return {
            ok: false,
            message: signUpResult.error.message || 'Unable to initialize account access.',
            applicationStatus: '',
            debugTrace: 'login-invalid-credentials -> auto-provision-signup-error',
          }
        }

        if (!canSignInNow) {
          const { error: immediateSignInError } = await supabase.auth.signInWithPassword({
            email: normalizedEmail,
            password,
          })

          if (!immediateSignInError) {
            canSignInNow = true
          }
        }

        if (canSignInNow) {
          setIsPortalAuthenticated(true)
          return {
            ok: true,
            applicationStatus: 'approved',
            debugTrace: 'login-invalid-credentials -> auto-provision-success',
          }
        }

        return {
          ok: false,
          message: (isAlreadyRegistered || isExistingAccount)
            ? 'Invalid login credentials. Use Forgot password to reset access.'
            : 'Account setup completed. Please sign in again.',
          applicationStatus: status || '',
          debugTrace: 'login-invalid-credentials -> auto-provision-signin-required',
        }
      }

      if (requireApproval) {
        const { data: adminRows, error: adminError } = await supabase
          .from(adminsTable)
          .select('email')
          .ilike('email', normalizedEmail)
          .limit(1)

        if (adminError) {
          await supabase.auth.signOut()
          return {
            ok: false,
            message: `Login blocked: admin status could not be verified (${adminError.message}).`,
            applicationStatus: '',
          }
        }

        if (adminRows?.length) {
          setIsPortalAuthenticated(true)
          return { ok: true, applicationStatus: 'approved' }
        }

        const registrationResult = await fetchLatestRegistrationByEmail(normalizedEmail, '*')
        const registrationError = registrationResult.error

        if (registrationError) {
          await supabase.auth.signOut()
          return {
            ok: false,
            message: `Login blocked: registration status could not be verified (${registrationError.message}).`,
            applicationStatus: '',
          }
        }

        const latestRegistration = registrationResult.data
        const status = String(latestRegistration?.status || '').trim().toLowerCase()
        const applicationType = getApplicationTypeFromRecord(latestRegistration)
        const isDistributorRegistration = applicationType === 'distributor'

        if (!latestRegistration) {
          if (isInternalBypassEmail) {
            setIsPortalAuthenticated(true)
            return { ok: true, applicationStatus: 'approved', debugTrace: 'login-success -> bypass-approved (no registration row)' }
          }

          setIsPortalAuthenticated(true)
          return {
            ok: true,
            applicationStatus: 'approved',
            debugTrace: 'login-success -> no-registration-row-allowed',
          }
        }

        if (isDistributorRegistration && requireApproval && status !== 'approved') {
          await supabase.auth.signOut()

          if (status === 'rejected') {
            return {
              ok: false,
              message: 'Your B2B application was rejected. Contact distribution support for next steps.',
              applicationStatus: 'rejected',
            }
          }

          if (status === 'pending') {
            return {
              ok: false,
              message: 'Your B2B application is pending approval. Access is enabled after manual review.',
              applicationStatus: 'pending',
            }
          }

          if (status === 'submitted') {
            return {
              ok: false,
              message: 'Your order request is stored and under processing. Portal sign-in requires an approved distributor application.',
              applicationStatus: 'submitted',
            }
          }

          return {
            ok: false,
            message: 'No approved B2B application found for this email.',
            applicationStatus: 'pending',
          }
        }

        try {
          const approvedRegistration = latestRegistration || null

          if (approvedRegistration) {
            const registrationProfile = buildClientProfileFromRegistration(approvedRegistration)

            try {
              const savedRaw = localStorage.getItem(CLIENT_PROFILE_STORAGE_KEY)
              const parsed = savedRaw ? JSON.parse(savedRaw) : null
              const currentLocal = parsed && typeof parsed === 'object' ? parsed : {}
              const mergedLocalProfile = {
                ...defaultClientProfile,
                ...currentLocal,
                ...registrationProfile,
              }
              localStorage.setItem(CLIENT_PROFILE_STORAGE_KEY, JSON.stringify(mergedLocalProfile))
            }
            catch {
              localStorage.setItem(CLIENT_PROFILE_STORAGE_KEY, JSON.stringify(registrationProfile))
            }

            const { data: userData } = await supabase.auth.getUser()
            const currentMeta = userData?.user?.user_metadata || {}

            await supabase.auth.updateUser({
              data: {
                ...currentMeta,
                ...buildUserMetadataFromRegistration(approvedRegistration),
              },
            })
          }
        }
        catch {
          // Non-blocking profile import.
        }
      }

      setIsPortalAuthenticated(true)
      return { ok: true, applicationStatus: 'approved', debugTrace: 'login-success -> approved' }
    }

    // Demo mode — skip credential check
    setIsPortalAuthenticated(true)
    return { ok: true, applicationStatus: 'approved', debugTrace: 'login-demo-mode -> approved' }
  }

  const handleAdminLogin = async (email, password) => {
    if (!hasSupabaseConfig || !supabase) {
      return { ok: false, message: 'Live auth is not configured.' }
    }

    const normalizedEmail = email.trim().toLowerCase()
    const { error: signInError } = await supabase.auth.signInWithPassword({ email: normalizedEmail, password })

    if (signInError) {
      if (/email not confirmed/i.test(signInError.message)) {
        return { ok: false, message: 'Your email address is not yet confirmed. Please check your inbox (and spam folder) for a confirmation link, then try again.' }
      }
      return { ok: false, message: signInError.message }
    }

    const { data: adminRows, error: adminError } = await supabase
      .from(adminsTable)
      .select('email')
      .ilike('email', normalizedEmail)
      .limit(1)

    if (adminError) {
      await supabase.auth.signOut()
      if (/does not exist/i.test(adminError.message)) {
        return { ok: false, message: 'Admin table not found. Please run supabase/sql/create_b2b_admins.sql in the Supabase SQL Editor.' }
      }
      return { ok: false, message: `Admin access check failed (${adminError.message}).` }
    }

    if (!adminRows?.length) {
      await supabase.auth.signOut()
      return { ok: false, message: `"${normalizedEmail}" is not registered as a B2B admin reviewer. Add it to the b2b_admins table in Supabase.` }
    }

    setIsPortalAuthenticated(true)
    setIsAdminSession(true)
    localStorage.setItem('gelitup.admin.session', 'true')
    return { ok: true }
  }

  const handleCreateAdminPassword = async ({ email, password, confirmPassword }) => {
    const normalizedEmail = String(email || '').trim().toLowerCase()

    if (!normalizedEmail) {
      return { ok: false, message: 'Admin email is required.' }
    }

    if (!password || password.length < 8) {
      return { ok: false, message: 'Password must be at least 8 characters.' }
    }

    if (password !== confirmPassword) {
      return { ok: false, message: 'Password and confirmation do not match.' }
    }

    if (!hasSupabaseConfig || !supabase) {
      return { ok: false, message: 'Live auth is not configured.' }
    }

    const signUpResult = await supabase.auth.signUp({
      email: normalizedEmail,
      password,
      options: {
        emailRedirectTo: `${window.location.origin}/portal/admin-login`,
      },
    })

    const signUpMessage = signUpResult?.error?.message || ''
    const isAlreadyRegistered = /already registered|already been registered/i.test(signUpMessage)
    const isExistingAccount = isExistingUserSignUpResult(signUpResult)
    const hasActiveSession = hasActiveSignUpSession(signUpResult)
    let canSignInNow = hasActiveSession

    if (signUpResult.error && !isAlreadyRegistered) {
      return { ok: false, message: signUpResult.error.message }
    }

    if (!canSignInNow) {
      const { error: immediateSignInError } = await supabase.auth.signInWithPassword({
        email: normalizedEmail,
        password,
      })

      if (!immediateSignInError) {
        canSignInNow = true
      }
    }

    if ((isAlreadyRegistered || isExistingAccount) && !canSignInNow) {
      return {
        ok: false,
        message: 'This admin account already exists. Use your existing password or reset it via Forgot password.',
      }
    }

    localStorage.setItem('adminRememberedEmail', normalizedEmail)

    if (canSignInNow) {
      const { data: adminRows, error: adminError } = await supabase
        .from(adminsTable)
        .select('email')
        .ilike('email', normalizedEmail)
        .limit(1)

      if (adminError) {
        await supabase.auth.signOut()
        return { ok: false, message: `Admin access check failed (${adminError.message}).` }
      }

      if (!adminRows?.length) {
        await supabase.auth.signOut()
        return { ok: false, message: 'This account is not registered as a B2B admin reviewer.' }
      }

      setIsPortalAuthenticated(true)
      setIsAdminSession(true)
      localStorage.setItem('gelitup.admin.session', 'true')
    }

    return {
      ok: true,
      message: canSignInNow
        ? 'Password created. Email confirmation is not required; you are now signed in as admin.'
        : 'Password setup completed. Please sign in as admin.',
      navigateToDashboard: canSignInNow,
    }
  }

  const handleCreatePortalPassword = async ({ email, password, confirmPassword, isRecoveryFlow = false }) => {
    const normalizedEmail = String(email || '').trim().toLowerCase()
    const isInternalBypassEmail = PORTAL_INTERNAL_BYPASS_EMAILS.has(normalizedEmail)

    if (!normalizedEmail) {
      return { ok: false, message: 'Business email is required.' }
    }

    if (!password || password.length < 8) {
      return { ok: false, message: 'Password must be at least 8 characters.' }
    }

    if (password !== confirmPassword) {
      return { ok: false, message: 'Password and confirmation do not match.' }
    }

    if (!hasSupabaseConfig || !supabase) {
      return { ok: false, message: 'Live auth is not configured.' }
    }

    // If the user arrived via a Supabase password-reset email link (isRecoveryFlow=true),
    // the SDK has already exchanged the code for a recovery session — call updateUser directly.
    if (isRecoveryFlow) {
      const { error: updateError } = await supabase.auth.updateUser({ password })
      if (updateError) {
        if (/not exist|invalid|expired/i.test(updateError.message || '')) {
          return { ok: false, message: 'Your reset link has expired. Please request a new password reset email.' }
        }
        return { ok: false, message: updateError.message || 'Password update failed.' }
      }
      setIsPortalAuthenticated(true)
      return {
        ok: true,
        infoMessage: 'Password updated successfully. You are now signed in.',
        navigateToDashboard: true,
        debugTrace: 'create-password -> recovery-updateUser',
      }
    }

    // Check if user already has an active session — this happens when they clicked
    // the B2B invite / email-confirmation link, which establishes a session via SIGNED_IN.
    const { data: { session: activeSession } } = await supabase.auth.getSession()
    if (activeSession) {
      const { error: updateError } = await supabase.auth.updateUser({ password })
      if (updateError) {
        return { ok: false, message: updateError.message || 'Unable to set your password. Please try again or use Forgot password.' }
      }
      localStorage.setItem('portalRememberedEmail', normalizedEmail)
      setIsPortalAuthenticated(true)
      return {
        ok: true,
        infoMessage: 'Password set. Welcome to the GEL.IT.UP B2B Portal!',
        navigateToDashboard: true,
        debugTrace: 'create-password -> email-confirmation-session -> updateUser',
      }
    }

    const signUpResult = await supabase.auth.signUp({
      email: normalizedEmail,
      password,
      options: {
        emailRedirectTo: `${window.location.origin}/portal/login`,
      },
    })

    const signUpMessage = signUpResult?.error?.message || ''
    const isAlreadyRegistered = /already registered|already been registered/i.test(signUpMessage)
    const isExistingAccount = isExistingUserSignUpResult(signUpResult)
    const hasActiveSession = hasActiveSignUpSession(signUpResult)
    let canSignInNow = hasActiveSession

    if (signUpResult.error && !isAlreadyRegistered) {
      return { ok: false, message: signUpResult.error.message }
    }

    if (!canSignInNow) {
      const { error: immediateSignInError } = await supabase.auth.signInWithPassword({
        email: normalizedEmail,
        password,
      })

      if (!immediateSignInError) {
        canSignInNow = true
      }
    }

    if ((isAlreadyRegistered || isExistingAccount) && !canSignInNow) {
      return {
        ok: false,
        message: 'This account already exists. Use your existing password or reset it via Forgot password.',
      }
    }

    localStorage.setItem('portalRememberedEmail', normalizedEmail)
    if (canSignInNow) {
      const registrationResult = await fetchLatestRegistrationByEmail(normalizedEmail, 'status, notes')
      const registrationError = registrationResult.error

      if (registrationError) {
        await supabase.auth.signOut()
        return { ok: false, message: `Registration status check failed (${registrationError.message}).` }
      }

      const latestRegistration = registrationResult.data || null
      if (!latestRegistration) {
        if (isInternalBypassEmail) {
          setIsPortalAuthenticated(true)
          return {
            ok: true,
            infoMessage: 'Password created successfully. Internal account access granted.',
            navigateToDashboard: true,
            debugTrace: 'create-password -> bypass-approved (no registration row)',
          }
        }

        setIsPortalAuthenticated(true)
        return {
          ok: true,
          infoMessage: 'Password created successfully. No B2B registration profile was found yet; submit a distributor application if approval-gated access is needed.',
          navigateToDashboard: true,
          debugTrace: 'create-password -> no-registration-row-allowed',
        }
      }

      const registrationStatus = String(latestRegistration?.status || '').trim().toLowerCase()
      const applicationType = getApplicationTypeFromRecord(latestRegistration)
      const isDistributorRegistration = applicationType === 'distributor'

      if (isDistributorRegistration && requireApproval && registrationStatus !== 'approved') {
        await supabase.auth.signOut()

        if (registrationStatus === 'rejected') {
          return { ok: false, message: 'Your distributor application was rejected. Contact distribution support for next steps.' }
        }

        return { ok: false, message: 'Your distributor application is pending approval. Access is enabled after manual review.' }
      }

      setIsPortalAuthenticated(true)
    }

    return {
      ok: true,
      infoMessage: canSignInNow
        ? 'Password created successfully. You are now signed in.'
        : 'confirm-email',
      navigateToDashboard: canSignInNow,
      debugTrace: canSignInNow ? 'create-password -> signed-in' : 'create-password -> account-ready-sign-in-required',
    }
  }

  const handlePortalRegister = async (application) => {
    if (hasSupabaseConfig && supabase) {
      const applicationType = String(application.applicationType || 'distributor').trim().toLowerCase()
      const orderProfile = String(application.orderProfile || 'business').trim().toLowerCase()
      const isDistributorApplication = applicationType === 'distributor'
      const isBusinessOrder = orderProfile !== 'personal'
      const shippingSameAsInvoice = application.shippingSameAsInvoice !== false
      const invoiceCountry = application.invoiceCountry.trim()
      const invoiceArea = application.invoiceArea.trim()
      const invoiceRegion = application.invoiceRegion.trim()
      const invoicePostalCode = application.invoicePostalCode.trim()
      const invoiceAddressLine1 = application.invoiceAddressLine1.trim()
      const yearsInBusiness = String(application.yearsInBusiness || '').trim()
      const distributionCountryInterests = String(application.distributionCountryInterests || '').trim()

      const shippingName = shippingSameAsInvoice ? application.contactName.trim() : application.shippingName.trim()
      const shippingPhone = shippingSameAsInvoice ? application.phone.trim() : application.shippingPhone.trim()
      const shippingAddressLine1 = shippingSameAsInvoice ? invoiceAddressLine1 : application.shippingAddressLine1.trim()
      const shippingAddressLine2 = shippingSameAsInvoice ? application.invoiceAddressLine2.trim() : application.shippingAddressLine2.trim()
      const shippingArea = shippingSameAsInvoice ? invoiceArea : application.shippingArea.trim()
      const shippingRegion = shippingSameAsInvoice ? invoiceRegion : application.shippingRegion.trim()
      const shippingCountry = shippingSameAsInvoice ? invoiceCountry : application.shippingCountry.trim()
      const shippingPostalCode = shippingSameAsInvoice ? invoicePostalCode : application.shippingPostalCode.trim()

      const isB2BOrderApplication = applicationType === 'b2b_order'

      const requiredFields = [
        ['client type', application.customerType],
        ['company/client name', application.companyName],
        ['contact name', application.contactName],
        ['contact email', application.contactEmail],
        ['phone', application.phone],
      ]

      if (isB2BOrderApplication) {
        requiredFields.push(['franchise / salon name', application.salonName])
      }

      if (isDistributorApplication) {
        requiredFields.push(
          ['shipping type', application.shippingType],
          ['invoice address line 1', invoiceAddressLine1],
          ['invoice area/city', invoiceArea],
          ['invoice region/state', invoiceRegion],
          ['invoice country', invoiceCountry],
          ['invoice postal code', invoicePostalCode],
        )
      }

      if (isDistributorApplication) {
        requiredFields.push(['VAT number', application.vatNumber])
      }

      if (isDistributorApplication) {
        requiredFields.push(
          ['business type', application.businessType],
          ['years in business', yearsInBusiness],
          ['distribution country interests', distributionCountryInterests],
        )
      }

      if (!shippingSameAsInvoice) {
        requiredFields.push(
          ['shipping contact name', shippingName],
          ['shipping phone', shippingPhone],
          ['shipping address line 1', shippingAddressLine1],
          ['shipping area/city', shippingArea],
          ['shipping region/state', shippingRegion],
          ['shipping country', shippingCountry],
          ['shipping postal code', shippingPostalCode],
        )
      }

      const missingField = requiredFields.find(([, value]) => !String(value || '').trim())
      if (missingField) {
        return { ok: false, message: `Please complete ${missingField[0]}.` }
      }

      // VAT prefix validation for known countries
      if (isDistributorApplication) {
        const vatPrefixErr = validateVatPrefix(application.vatNumber, invoiceCountry)
        if (vatPrefixErr) {
          return { ok: false, message: vatPrefixErr }
        }
      }

      const submissionStatus = isDistributorApplication ? 'pending' : 'approved'
      const derivedBusinessType = isDistributorApplication
        ? application.businessType.trim()
        : `B2B Order - ${isBusinessOrder ? 'Business' : 'Personal'}`

      const notesSections = [
        `[APPLICATION_TYPE:${isDistributorApplication ? 'distributor' : 'b2b_order'}]`,
        `[ORDER_PROFILE:${isBusinessOrder ? 'business' : 'personal'}]`,
      ]

      if (isDistributorApplication) {
        notesSections.push(
          `Years in business: ${yearsInBusiness}`,
          `Distribution country interests: ${distributionCountryInterests}`,
        )
      }

      if (application.notes?.trim()) {
        notesSections.push(`Additional notes: ${application.notes.trim()}`)
      }

      const payload = {
        customer_type: application.customerType.trim(),
        company_name: application.companyName.trim(),
        vat_number: application.vatNumber?.trim() || 'N/A',
        contact_name: application.contactName.trim(),
        contact_email: application.contactEmail.trim().toLowerCase(),
        phone: application.phone.trim(),
        website: application.website.trim() || null,
        shipping_type: application.shippingType.trim(),
        address: invoiceAddressLine1,
        city: invoiceArea,
        postal_code: invoicePostalCode,
        country: invoiceCountry,
        invoice_address_line1: invoiceAddressLine1,
        invoice_address_line2: application.invoiceAddressLine2.trim() || null,
        invoice_area: invoiceArea,
        invoice_region: invoiceRegion,
        invoice_country: invoiceCountry,
        invoice_postal_code: invoicePostalCode,
        shipping_same_as_invoice: shippingSameAsInvoice,
        shipping_name: shippingName || null,
        shipping_phone: shippingPhone || null,
        shipping_address_line1: shippingAddressLine1 || null,
        shipping_address_line2: shippingAddressLine2 || null,
        shipping_area: shippingArea || null,
        shipping_region: shippingRegion || null,
        shipping_country: shippingCountry || null,
        shipping_postal_code: shippingPostalCode || null,
        business_type: derivedBusinessType,
        application_type: isDistributorApplication ? 'distributor' : 'b2b_order',
        distributor_tier: isDistributorApplication ? (application.distributorTier || null) : null,
        order_profile: isBusinessOrder ? 'business' : 'personal',
        prices_allocated: !isDistributorApplication,
        admin_comment: null,
        order_action: null,
        order_payment_status: isDistributorApplication ? null : 'unpaid',
        order_shipping_status: isDistributorApplication ? null : 'not_ready',
        tracking_number: null,
        tracking_url: null,
        action_updated_at: null,
        action_updated_by: null,
        notes: notesSections.join('\n'),
        status: submissionStatus,
      }

      const { error } = await supabase
        .from(registrationsTable)
        .insert([payload])
      const createdApplication = { id: null, contact_name: payload.contact_name, contact_email: payload.contact_email, company_name: payload.company_name }

      if (error) {
        const missingTableError = error.message?.includes('Could not find the table')
          || error.message?.includes('does not exist')

        if (missingTableError) {
          return {
            ok: false,
            message: `Registration failed: table \`${registrationsTable}\` is missing in Supabase. Run SQL from /supabase/sql/create_b2b_registrations.sql and retry.`,
          }
        }

        return { ok: false, message: `Registration failed: ${error.message} (code: ${error.code})` }
      }

      const inboxTo = isDistributorApplication ? ORDER_INBOX_EMAIL : CONTACT_INBOX_EMAIL
      const inboxSubject = isDistributorApplication
        ? `[DISTRIBUTOR APPLICATION] #${createdApplication?.id} — ${payload.company_name}`
        : `[NEW ORDER REQUEST] #${createdApplication?.id} — ${payload.company_name}`
      const inboxHtml = isDistributorApplication
        ? `<div style="font-family:sans-serif;max-width:600px;">
            <div style="background:#4f46e5;color:#fff;padding:16px 24px;border-radius:8px 8px 0 0;">
              <strong style="font-size:13px;letter-spacing:2px;text-transform:uppercase;">Distributor Application</strong>
            </div>
            <div style="border:1px solid #e5e7eb;border-top:none;padding:20px 24px;border-radius:0 0 8px 8px;">
              <p style="margin:0 0 12px;"><strong>Application ID:</strong> ${createdApplication?.id}</p>
              <p style="margin:0 0 8px;"><strong>Company:</strong> ${payload.company_name}</p>
              <p style="margin:0 0 8px;"><strong>Contact:</strong> ${payload.contact_name} (<a href="mailto:${payload.contact_email}">${payload.contact_email}</a>)</p>
              <p style="margin:0 0 8px;"><strong>Status:</strong> ${payload.status}</p>
              <p style="margin:0 0 8px;"><strong>Distribution Tier:</strong> ${payload.distributor_tier || 'N/A'}</p>
              <p style="margin:0 0 8px;"><strong>Business Type:</strong> ${payload.business_type}</p>
              <p style="margin:0 0 8px;"><strong>VAT:</strong> ${payload.vat_number || 'N/A'}</p>
              <p style="margin:0;"><strong>Invoice Country:</strong> ${payload.invoice_country}</p>
            </div>
          </div>`
        : `<div style="font-family:sans-serif;max-width:600px;">
            <div style="background:#16a34a;color:#fff;padding:16px 24px;border-radius:8px 8px 0 0;">
              <strong style="font-size:13px;letter-spacing:2px;text-transform:uppercase;">&#128722; New B2B Registration Request</strong>
            </div>
            <div style="border:1px solid #e5e7eb;border-top:none;padding:20px 24px;border-radius:0 0 8px 8px;">
              <p style="margin:0 0 12px;"><strong>Registration ID:</strong> ${createdApplication?.id}</p>
              <p style="margin:0 0 8px;"><strong>Franchise / Salon:</strong> ${payload.company_name}</p>
              <p style="margin:0 0 8px;"><strong>Contact:</strong> ${payload.contact_name} (<a href="mailto:${payload.contact_email}">${payload.contact_email}</a>)</p>
              <p style="margin:0 0 8px;"><strong>Business Type:</strong> ${payload.business_type}</p>
              <p style="margin:0 0 8px;"><strong>VAT:</strong> ${payload.vat_number || 'N/A'}</p>
              <p style="margin:0;"><strong>Invoice Country:</strong> ${payload.invoice_country}</p>
            </div>
          </div>`

      const [inboxNotificationResult, applicantNotificationResult] = await Promise.all([
        sendPortalEmailNotification({
          eventType: isDistributorApplication ? 'distributor_application_submitted' : 'b2b_order_request_submitted',
          to: inboxTo,
          subject: inboxSubject,
          html: inboxHtml,
          applicationId: createdApplication?.id,
          companyName: payload.company_name,
          contactName: payload.contact_name,
          status: payload.status,
        }),
        sendPortalEmailNotification({
          eventType: 'application_received',
          to: payload.contact_email,
          subject: `${isDistributorApplication ? 'Distributor application received' : 'B2B registration request received'}: ${payload.company_name}`,
          html: isDistributorApplication
            ? `<p>Hello ${payload.contact_name},</p><p>Welcome to <strong>GEL.IT.UP by GIUP®</strong>.</p><p>Thank you for submitting your distributor information for <strong>${payload.company_name}</strong>.</p><p>Your submission has been sent to ${ORDER_INBOX_EMAIL}. You will soon receive an approval email confirming that you can log in to the portal.</p><p>Best regards,<br/>GEL.IT.UP Distribution Team</p>`
            : `<p>Hello ${payload.contact_name},</p><p>Thank you for your B2B registration request for <strong>${payload.company_name}</strong>.</p><p>Your request has been received and stored in our admin portal. Our team will review it and be in touch shortly.</p><p>Best regards,<br/>GEL.IT.UP Distribution Team</p>`,
          applicationId: createdApplication?.id,
          companyName: payload.company_name,
          contactName: payload.contact_name,
        }),
      ])

      if (!applicantNotificationResult.ok && !applicantNotificationResult.skipped) {
        return {
          ok: true,
          message: `Submission stored, but confirmation email failed: ${applicantNotificationResult.message}`,
        }
      }

      if (!inboxNotificationResult.ok && !inboxNotificationResult.skipped) {
        return {
          ok: true,
          message: `Submission stored, but inbox notification failed: ${inboxNotificationResult.message}`,
        }
      }

      if (applicantNotificationResult.skipped || inboxNotificationResult.skipped) {
        return {
          ok: true,
          message: 'Submission stored. Email webhook is not configured yet.',
        }
      }

      // For B2B orders: create the Supabase auth account immediately so that Supabase
      // sends the email-confirmation link. The link redirects to create-password.
      if (!isDistributorApplication) {
        const contactEmail = payload.contact_email
        const encodedEmail = encodeURIComponent(contactEmail)
        const tempPass = `${crypto.randomUUID()}-Gu!${Date.now()}`
        await supabase.auth.signUp({
          email: contactEmail,
          password: tempPass,
          options: {
            emailRedirectTo: `${window.location.origin}/portal/login?mode=create-password&email=${encodedEmail}`,
          },
        })
        // Ignore signUp errors — user may already have an account; this is best-effort
      }

      return {
        ok: true,
        message: isDistributorApplication
          ? `Your distributor application has been received. Our team will review it and contact you by email once approved — usually within 1–2 business days.`
          : `check-inbox:${payload.contact_email}`,
      }
    }

    const missingEnvVars = [
      !import.meta.env.VITE_SUPABASE_URL ? 'VITE_SUPABASE_URL' : null,
      !import.meta.env.VITE_SUPABASE_ANON_KEY ? 'VITE_SUPABASE_ANON_KEY' : null,
    ].filter(Boolean)

    return {
      ok: false,
      message: missingEnvVars.length
        ? `Live registration is not configured. Missing env: ${missingEnvVars.join(', ')}`
        : 'Live registration is not configured.',
    }
  }

  const handleSubmitContactRequest = async () => {
    const contactName = String(contactRequestForm.name || '').trim()
    const contactEmail = String(contactRequestForm.email || '').trim().toLowerCase()
    const contactPhone = String(contactRequestForm.phone || '').trim()

    if (!contactName || !contactEmail || !contactPhone) {
      setContactRequestError('Name, email address, and contact number are required.')
      return
    }

    if (!hasSupabaseConfig || !supabase) {
      setContactRequestError('Contact form is unavailable because portal storage is not configured.')
      return
    }

    setIsSubmittingContactRequest(true)
    setContactRequestError('')
    setContactRequestMessage('')

    const payload = {
      customer_type: 'company',
      company_name: 'Contact Request',
      vat_number: 'N/A',
      contact_name: contactName,
      contact_email: contactEmail,
      phone: contactPhone,
      shipping_type: 'road',
      address: 'N/A',
      city: 'N/A',
      postal_code: 'N/A',
      country: 'N/A',
      business_type: 'contact_request',
      application_type: 'contact_request',
      status: 'submitted',
      notes: '[CONTACT_REQUEST] Public contact modal submission.',
      order_profile: null,
      admin_comment: null,
      order_action: null,
      order_payment_status: null,
      order_shipping_status: null,
      tracking_number: null,
      tracking_url: null,
      action_updated_at: null,
      action_updated_by: null,
    }

    const { data: createdRequest, error } = await supabase
      .from(registrationsTable)
      .insert([payload])
      .select('id')
      .single()

    if (error) {
      setIsSubmittingContactRequest(false)
      setContactRequestError(error.message || 'Unable to save contact request.')
      return
    }

    const notificationResult = await sendPortalEmailNotification({
      eventType: 'contact_request_submitted',
      to: CONTACT_INBOX_EMAIL,
      subject: `Contact Request #${createdRequest?.id} — ${contactName}`,
      html: `<p>New contact request submitted.</p><p><strong>Request ID:</strong> ${createdRequest?.id}</p><p><strong>Name:</strong> ${contactName}</p><p><strong>Email:</strong> ${contactEmail}</p><p><strong>Phone:</strong> ${contactPhone}</p>`,
      applicationId: createdRequest?.id,
      contactName,
      status: 'submitted',
    })

    setIsSubmittingContactRequest(false)

    if (!notificationResult.ok && !notificationResult.skipped) {
      setContactRequestError(`Request saved, but notification email failed: ${notificationResult.message}`)
      return
    }

    setContactRequestMessage(`Thanks. Your message has been submitted and sent to ${CONTACT_INBOX_EMAIL}.`)
    setContactRequestForm({ name: '', email: '', phone: '' })
  }

  const handleResendConfirmation = async (email) => {
    if (!email) {
      return { ok: false, message: 'Enter your email first.' }
    }

    return { ok: false, message: 'Email confirmation is disabled. Use Forgot password if you need to reset access.' }
  }

  const handleCheckApproval = async (email) => {
    if (!email) {
      return { ok: false, message: 'Enter your business email first.' }
    }

    if (!hasSupabaseConfig || !supabase) {
      return { ok: false, message: 'Live auth is not configured.' }
    }

    const normalizedEmail = email.trim().toLowerCase()

    const registrationResult = await fetchLatestRegistrationByEmail(normalizedEmail, 'status, notes')
    const error = registrationResult.error

    if (error) {
      return { ok: false, message: error.message }
    }

    const latestRegistration = registrationResult.data || null
    if (!latestRegistration) {
      return { ok: true, applicationStatus: 'pending' }
    }

    const status = String(latestRegistration?.status || '').trim().toLowerCase() || 'pending'
    const applicationType = getApplicationTypeFromRecord(latestRegistration)
    const isDistributorRegistration = applicationType === 'distributor'

    if (!isDistributorRegistration) {
      return { ok: true, applicationStatus: 'approved' }
    }

    return { ok: true, applicationStatus: status }
  }

  const handlePortalLogout = async () => {
    if (hasSupabaseConfig && supabase) {
      await supabase.auth.signOut()
    }

    setIsPortalAuthenticated(false)
    setIsAdminSession(false)
    localStorage.removeItem('portalAuth')
    localStorage.removeItem('gelitup.admin.session')
  }

  const isPortalRoute = location.pathname.startsWith('/portal') || location.pathname === '/admin-login'

  return (
    <div className="lux-theme min-h-screen pb-8">
      <ScrollToTopOnRouteChange />
      <header className="sticky top-0 z-40 border-b border-white/15 bg-black/80 backdrop-blur-[10px]">
        <div className="mx-auto flex max-w-6xl items-center justify-between px-3 py-2.5 md:px-6 md:py-3">
          <NavLink to="/" className="flex items-center gap-3 group">
            <img src={appLogo} alt="GEL.IT.UP by GIUP® logo" className="max-h-8 w-auto object-contain md:max-h-9" />
            <div>
              <p className="text-xs font-black uppercase leading-none tracking-[0.07em] text-white md:text-sm md:tracking-[0.08em]">GEL.IT.UP</p>
              <p className="text-[11px] text-white/65 md:text-xs">Professional Nail Supplies</p>
            </div>
          </NavLink>
          <Nav />
        </div>
      </header>

      <main className={`mx-auto max-w-6xl px-3 py-4 md:px-6 md:py-10 ${isPortalRoute ? 'portal-luxe' : ''}`}>
        <Routes>
          <Route
            path="/"
            element={<HomePage />}
          />
          <Route path="/home" element={<HomePage />} />
          <Route
            path="/about-us"
            element={<Navigate to="/pages/about-us" replace />}
          />
          <Route path="/our-products" element={<Navigate to="/distributor-packages" replace />} />
          <Route
            path="/distributors"
            element={<DistributorsPage />}
          />

          <Route path="/products" element={<Navigate to="/distributor-packages" replace />} />
          <Route path="/distributor-packages" element={<DistributorPackagesPage />} />
          <Route path="/for-academies" element={<ForAcademiesPage />} />
          <Route path="/full-catalogue" element={<FullCataloguePage />} />
          <Route path="/checkout" element={<CheckoutPage />} />
          <Route path="/admin/missing-images" element={isAdminSession ? <MissingImagesReport /> : <Navigate to="/portal/admin-login" replace />} />
          <Route path="/catalogue" element={<Navigate to="/full-catalogue" replace />} />
          <Route path="/packages" element={<Navigate to="/distributor-packages" replace />} />
          <Route path="/guestbook" element={<GuestbookPage />} />
          <Route path="/inspiration" element={<InspirationPage />} />
          <Route path="/privacy-policy" element={<PrivacyPolicyPage />} />
          <Route path="/cookie-policy" element={<CookiePolicyPage />} />
          <Route path="/terms-and-conditions" element={<TermsAndConditionsPage />} />
          <Route path="/certifications" element={<HomePage />} />
          <Route path="/contact" element={<Navigate to="/become-distributor" replace />} />
          <Route path="/baseline" element={<Navigate to="/" replace />} />
          <Route path="/baseline/:slug" element={<Navigate to="/" replace />} />

          <Route path="/application-services" element={<Navigate to="/become-distributor" replace />} />
          <Route path="/application-services/*" element={<Navigate to="/become-distributor" replace />} />
          <Route path="/pages/:slug" element={<ImportedAnyPage />} />
          <Route path="/become-distributor" element={<PortalRegister onRegister={handlePortalRegister} />} />

          {PORTAL_ENABLED
            ? (
              <>
                <Route path="/portal" element={<PortalLanding />} />
                <Route
                  path="/portal/login"
                  element={(
                    <PortalLogin
                      onLogin={handlePortalLogin}
                      onCreatePassword={handleCreatePortalPassword}
                      pendingRecoverySession={pendingRecoverySession}
                      onRecoverySessionConsumed={() => setPendingRecoverySession(false)}
                    />
                  )}
                />
                <Route
                  path="/portal/admin-login"
                  element={<PortalAdminLogin onAdminLogin={handleAdminLogin} onAdminCreatePassword={handleCreateAdminPassword} />}
                />
                <Route
                  path="/portal/admin-login/*"
                  element={<PortalAdminLogin onAdminLogin={handleAdminLogin} onAdminCreatePassword={handleCreateAdminPassword} />}
                />
                <Route path="/admin-login" element={<Navigate to="/portal/admin-login" replace />} />
                <Route path="/portal-client-login" element={<Navigate to="/portal/login" replace />} />
                <Route path="/portal-admin-login" element={<Navigate to="/portal/admin-login" replace />} />
                <Route path="/portal/register" element={<PortalRegister onRegister={handlePortalRegister} />} />
                <Route path="/portal/buy" element={<BuyerRegister />} />
                <Route path="/portal/forgot-password" element={<PortalForgotPassword />} />
                <Route
                  path="/portal/dashboard/:module"
                  element={<ProtectedPortal authReady={authReady} isAuthenticated={isPortalAuthenticated} isAdmin={isAdminSession} onLogout={handlePortalLogout} />}
                />
                <Route path="/portal/products" element={<Navigate to="/portal/dashboard/products" replace />} />
                <Route path="/portal/solid-colours" element={<Navigate to="/portal/dashboard/products" replace />} />
                <Route path="/portal/dashboard/solid-colours" element={<Navigate to="/portal/dashboard/products" replace />} />
                <Route path="/portal/dashboard" element={<Navigate to="/portal/dashboard/overview" replace />} />
              </>
            )
            : (
              <>
                <Route path="/portal/*" element={<PortalAccessNotice />} />
                <Route path="/admin-login" element={<PortalAccessNotice />} />
              </>
            )}

          <Route path="*" element={<NotFoundPage />} />
        </Routes>
      </main>

      {/* Exit-intent popup for visitors with items in cart */}
      {showExitIntent && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/70 backdrop-blur-sm" onClick={() => setShowExitIntent(false)}>
          <div className="relative mx-4 w-full max-w-md overflow-hidden rounded-3xl bg-[#111] shadow-2xl ring-1 ring-white/10" onClick={(e) => e.stopPropagation()}>
            <button
              type="button"
              aria-label="Close"
              onClick={() => setShowExitIntent(false)}
              className="absolute right-3 top-3 z-10 flex h-8 w-8 items-center justify-center rounded-full bg-white/10 text-white/60 transition hover:bg-white/20 hover:text-white"
            >
              <svg viewBox="0 0 24 24" fill="none" className="h-4 w-4" stroke="currentColor" strokeWidth="2"><path d="M18 6 6 18M6 6l12 12"/></svg>
            </button>
            <div className="bg-gradient-to-br from-fuchsia-600 to-purple-700 px-8 py-10 text-center">
              <p className="text-4xl">🛒✨</p>
              <h2 className="mt-3 text-2xl font-extrabold text-white">Wait — your cart is calling!</h2>
              <p className="mt-2 text-sm text-white/80">You've picked some gorgeous products. Don't let them slip away!</p>
            </div>
            <div className="space-y-3 px-8 py-6">
              <NavLink
                to="/portal/register"
                onClick={() => setShowExitIntent(false)}
                className="flex w-full items-center justify-center gap-2 rounded-xl bg-fuchsia-600 px-5 py-3 text-sm font-bold text-white shadow-lg transition hover:bg-fuchsia-500"
              >
                Register to save my cart →
              </NavLink>
              <NavLink
                to="/portal/login"
                onClick={() => setShowExitIntent(false)}
                className="flex w-full items-center justify-center gap-2 rounded-xl border border-white/20 bg-white/5 px-5 py-3 text-sm font-semibold text-white/80 transition hover:bg-white/10"
              >
                I already have an account
              </NavLink>
              <button
                type="button"
                onClick={() => setShowExitIntent(false)}
                className="w-full pt-1 text-center text-xs text-white/40 transition hover:text-white/60"
              >
                No thanks, I'll keep browsing
              </button>
            </div>
          </div>
        </div>
      )}

      {!hasAcceptedCookies && (
        <div className="fixed bottom-4 left-0 right-0 z-40 px-3 md:px-6">
          <div className="mx-auto flex max-w-6xl flex-col gap-3 rounded-xl border border-white/20 bg-black/90 p-3 text-white shadow-sm backdrop-blur-[10px] sm:flex-row sm:items-center sm:justify-between">
            <p className="text-xs text-white/80">
              We use cookies to improve your experience. By continuing, you agree to our cookie use.
              {' '}
              <NavLink to="/cookie-policy" className="font-semibold text-fuchsia-300 underline">Read Cookie Policy</NavLink>
            </p>
            <button
              type="button"
              onClick={handleAcceptCookies}
              className="rounded-lg bg-fuchsia-600 px-3 py-2 text-xs font-semibold text-white transition duration-300 hover:bg-fuchsia-500"
            >
              Accept Cookies
            </button>
          </div>
        </div>
      )}

      <footer className="mx-auto mt-6 max-w-6xl space-y-5 rounded-2xl border border-white/15 bg-black/85 px-3 pb-4 pt-4 text-xs text-white/80 backdrop-blur-[10px] md:mt-8 md:px-6 md:pt-5">
        <div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-5">
          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-white/55">{T ? 'Azienda' : 'Company'}</p>
            <p className="mt-2 text-sm font-semibold text-white">GEL.IT.UP by GIUP® Professional</p>
            <p className="mt-1">{T ? 'Rete Globale di Distribuzione Professionale' : 'Global Professional Distribution Network'}</p>
          </div>

          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-white/55">{T ? 'Contatto' : 'Contact'}</p>
            <a href={`tel:${String(PROFORMA_LEEUKOPF_PHONE || '').replace(/[\s()]/g, '')}`} className="mt-2 block transition hover:text-fuchsia-300">{PROFORMA_LEEUKOPF_PHONE}</a>
            <a href="mailto:info@gelitup.com" className="mt-2 inline-flex items-center gap-2 transition hover:text-fuchsia-300">
              <svg viewBox="0 0 24 24" fill="none" aria-hidden="true" className="h-4 w-4 shrink-0">
                <rect x="3.5" y="5.5" width="17" height="13" rx="2" stroke="currentColor" strokeWidth="1.8" />
                <path d="M4 6.5l8 5.5 8-5.5" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" />
              </svg>
              info@gelitup.com
            </a>
            <a
              href={SUPPORT_WHATSAPP_URL}
              target="_blank"
              rel="noreferrer"
              className="mt-2 inline-flex items-center gap-1.5 text-green-400 transition hover:text-green-300"
            >
              <svg viewBox="0 0 24 24" className="h-3.5 w-3.5 fill-current" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
                <path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.570-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.570-.347z"/>
                <path d="M12 0C5.373 0 0 5.373 0 12c0 2.122.554 4.112 1.522 5.836L.057 23.928a.5.5 0 00.608.593l6.358-1.43A11.95 11.95 0 0012 24c6.627 0 12-5.373 12-12S18.627 0 12 0zm0 21.818a9.808 9.808 0 01-4.985-1.356l-.357-.213-3.704.833.886-3.576-.233-.369A9.818 9.818 0 012.182 12C2.182 6.57 6.57 2.182 12 2.182S21.818 6.57 21.818 12 17.43 21.818 12 21.818z"/>
              </svg>
              {T ? 'Supporto WhatsApp' : 'WhatsApp Support'}
            </a>
          </div>

          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-white/55">Menu</p>
            <div className="mt-2 space-y-1.5">
              <NavLink to="/" className="block transition duration-300 hover:text-fuchsia-300">Home</NavLink>
              <NavLink to="/about-us" className="block transition duration-300 hover:text-fuchsia-300">{T ? 'Chi Siamo' : 'About Us'}</NavLink>
              <NavLink to="/full-catalogue" className="block transition duration-300 hover:text-fuchsia-300">{T ? 'Catalogo' : 'Catalogue'}</NavLink>
              <NavLink to="/distributor-packages" className="block transition duration-300 hover:text-fuchsia-300">{T ? 'Opzioni di Distribuzione' : 'Distribution Options'}</NavLink>
              <NavLink to="/become-distributor" className="block transition duration-300 hover:text-fuchsia-300">{T ? 'Diventa Distributore' : 'Become Distributor'}</NavLink>
              <NavLink to="/guestbook" className="block transition duration-300 hover:text-fuchsia-300">{T ? 'Guestbook' : 'Guestbook'}</NavLink>
              <NavLink to="/portal/register" className="block transition duration-300 hover:text-fuchsia-300">{T ? 'Registrazione Cliente' : 'Client Registration'}</NavLink>
            </div>
          </div>

          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-white/55">{T ? 'Legale' : 'Legal'}</p>
            <div className="mt-2 space-y-1.5">
              <NavLink to="/privacy-policy" className="block transition duration-300 hover:text-fuchsia-300">{T ? 'Informativa sulla Privacy' : 'Privacy Policy'}</NavLink>
              <NavLink to="/cookie-policy" className="block transition duration-300 hover:text-fuchsia-300">Cookie Policy</NavLink>
              <NavLink to="/terms-and-conditions" className="block transition duration-300 hover:text-fuchsia-300">{T ? 'Termini e Condizioni' : 'Terms and Conditions'}</NavLink>
            </div>
          </div>

          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-white/55">{T ? 'Connettiti' : 'Connect'}</p>
            <div className="mt-2 space-y-2">
              {FOOTER_SOCIAL_LINKS.map((social) => (
                <a
                  key={social.key}
                  href={social.href}
                  target="_blank"
                  rel="noreferrer"
                  className="flex items-center gap-2 transition duration-300 hover:text-fuchsia-300"
                >
                  <span className="inline-flex h-6 w-6 items-center justify-center rounded-md border border-white/30 text-white/85">
                    <FooterSocialIcon platform={social.key} />
                  </span>
                  <span className="font-medium">{social.label}</span>
                  <span className="text-white/55">{social.handle}</span>
                </a>
              ))}

            </div>
          </div>
        </div>

        <p className="border-t border-white/15 pt-3 text-white/55">{T ? T.footer.rights : '— 2026 GEL.IT.UP by GIUP®'}</p>
      </footer>

      {/* Floating chat widget + back-to-top */}
      <div className="fixed z-50 flex flex-col items-end gap-2" style={{ bottom: 'calc(24px + env(safe-area-inset-bottom, 0px))', right: 'calc(12px + env(safe-area-inset-right, 0px))' }}>
        {/* Expandable chat panel */}
        {showChatPanel && (
          <div className="mb-1 w-64 rounded-2xl border border-white/10 bg-[#1a1a1a] shadow-2xl">
            <div className="flex items-center justify-between border-b border-white/10 px-4 py-3">
              <p className="text-sm font-semibold text-white">Chat with us</p>
              <button
                type="button"
                aria-label="Close chat panel"
                onClick={() => setShowChatPanel(false)}
                className="text-white/50 hover:text-white"
              >
                <svg viewBox="0 0 24 24" fill="none" className="h-4 w-4" stroke="currentColor" strokeWidth="2"><path d="M18 6 6 18M6 6l12 12"/></svg>
              </button>
            </div>
            <div className="flex flex-col gap-2 p-3">
              {/* WhatsApp */}
              <a
                href={SUPPORT_WHATSAPP_URL}
                target="_blank"
                rel="noreferrer"
                className="flex items-center gap-3 rounded-xl bg-[#25D366]/15 px-3 py-2.5 transition hover:bg-[#25D366]/25"
              >
                <svg viewBox="0 0 24 24" fill="currentColor" className="h-6 w-6 shrink-0 text-[#25D366]">
                  <path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413z"/>
                </svg>
                <div>
                  <p className="text-sm font-semibold text-white">WhatsApp</p>
                  <p className="text-[11px] text-white/55">English support</p>
                </div>
              </a>
              {/* Viber */}
              <a
                href={SUPPORT_VIBER_URL}
                target="_blank"
                rel="noreferrer"
                className="flex items-center gap-3 rounded-xl bg-[#7360f2]/15 px-3 py-2.5 transition hover:bg-[#7360f2]/25"
              >
                <svg viewBox="0 0 24 24" fill="currentColor" className="h-6 w-6 shrink-0 text-[#7360f2]">
                  <path d="M11.992 2C6.256 2 2 6.03 2 11.578c0 2.704 1.076 5.136 3.017 6.887V21l2.834-1.56c.747.204 1.538.314 2.353.314.122 0 .243-.003.364-.008C10.91 19.81 11.45 20 12 20c3.866 0 7-2.686 7-6s-3.134-6-7-6c-.003 0-.006 0-.01 0zM7.5 9.5c.276 0 .5.224.5.5v.01c0 .276-.224.5-.5.5S7 10.286 7 10.01V10c0-.276.224-.5.5-.5zm4 0c.276 0 .5.224.5.5v.01c0 .276-.224.5-.5.5s-.5-.224-.5-.5V10c0-.276.224-.5.5-.5zm4 0c.276 0 .5.224.5.5v.01c0 .276-.224.5-.5.5s-.5-.224-.5-.5V10c0-.276.224-.5.5-.5zm-8.938 2.964c.343 2.69 2.518 4.846 5.215 5.183l-.043.037c-.413.35-.882.537-1.359.537-.395 0-.791-.118-1.157-.35l-.337-.215-1.693.932.455-1.554-.25-.32A7.014 7.014 0 012.999 11.59c0-2.33 1.096-4.408 2.82-5.77A8.058 8.058 0 002 11.578c0 1.873.641 3.603 1.715 4.982l-.618 2.112 2.165-1.191c.535.285 1.1.43 1.672.43.87 0 1.713-.3 2.428-.858A7.023 7.023 0 018 14c0-3.866 3.134-7 7-7 .341 0 .677.025 1.006.072C14.485 4.81 11.44 2 7.562 2z"/>
                </svg>
                <div>
                  <p className="text-sm font-semibold text-white">Viber</p>
                  <p className="text-[11px] text-white/55">Multilingual · auto-translate</p>
                </div>
              </a>
              <p className="px-1 pt-1 text-[10px] text-white/30">Opens in a new tab — you won't lose your place.</p>
            </div>
          </div>
        )}
        {/* WhatsApp direct link — always visible */}
        <a
          href={SUPPORT_WHATSAPP_URL}
          target="_blank"
          rel="noreferrer"
          aria-label="Chat with us on WhatsApp"
          className="flex items-center gap-2.5 rounded-full bg-[#111111] pl-3 pr-5 py-2.5 shadow-[0_4px_20px_rgba(0,0,0,0.5)] ring-1 ring-white/10 transition duration-300 hover:bg-[#1a1a1a] active:scale-95"
        >
          <svg viewBox="0 0 24 24" fill="currentColor" className="h-7 w-7 shrink-0 text-[#25D366]">
            <path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413z"/>
          </svg>
          <span className="flex flex-col leading-tight">
            <span className="text-sm font-bold text-white">WhatsApp</span>
            <span className="text-[10px] font-medium text-[#25D366]">click to chat</span>
          </span>
        </a>
        {/* Toggle Viber/other channels */}
        <button
          type="button"
          aria-label={showChatPanel ? 'Close chat options' : 'More chat options'}
          onClick={() => setShowChatPanel(p => !p)}
          className="flex h-10 w-10 items-center justify-center rounded-full bg-[#111111] shadow-lg ring-1 ring-white/10 transition duration-300 hover:bg-[#1a1a1a] active:scale-95"
        >
          {showChatPanel
            ? <svg viewBox="0 0 24 24" fill="none" className="h-4 w-4 text-white/70" stroke="currentColor" strokeWidth="2"><path d="M18 6 6 18M6 6l12 12"/></svg>
            : <svg viewBox="0 0 24 24" fill="none" className="h-4 w-4 text-white/70" stroke="currentColor" strokeWidth="2"><path d="M12 5v.01M12 12v.01M12 19v.01M12 6a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2z"/></svg>
          }
        </button>
        <button
          type="button"
          aria-label="Back to top"
          onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}
          className={`flex h-9 w-9 items-center justify-center rounded-xl border border-gray-200 bg-white text-gray-700 shadow-xl transition duration-300 hover:border-fuchsia-500 hover:bg-fuchsia-600 hover:text-white ${
            showBackToTop ? 'opacity-100 translate-y-0 pointer-events-auto' : 'opacity-0 translate-y-4 pointer-events-none'
          }`}
        >
          <svg viewBox="0 0 24 24" fill="none" aria-hidden="true" className="h-4 w-4">
            <path d="M12 19V5M5 12l7-7 7 7" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
        </button>
      </div>

      <MobileNav />
      <PWABadge />
    </div>
  )
}

export default App
